test("CAT-284: follows the cursor past pages shortened by deleted rows", () => {
  const gateway = new MemoryGateway({ invoices: [{id:"i-1",name:"A"},{id:"i-2",name:"B",deleted:true},{id:"i-3",name:"C"}] });
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:2}).entries.map(r=>r.id), ["i-1","i-3"]);
  assert.deepEqual(gateway.requests.map(r=>r.cursor), [null,"2"]);
});
test("projects are paged with the requested pageSize", () => {
  const gateway = new MemoryGateway({ projects: [{id:"1",name:"One"},{id:"2",name:"Old",deleted:true},{id:"3",name:"Three"}] });
  assert.deepEqual(exportCatalog(gateway, "projects", {pageSize:2}).entries.map(r=>r.id), ["1","3"]);
  assert.ok(gateway.requests.every(r=>r.limit===2));
});
test("an empty cursor token continues the scan", () => {
  const pages: Record<string, {items:{id:string;name:string}[];next:string|null}> = {
    start: { items: [{id:"1",name:"One"}], next: "" },
    "": { items: [{id:"2",name:"Two"}], next: null },
  };
  const gateway = { fetch: (_c: string, cursor: string | null) => pages[cursor ?? "start"] };
  assert.deepEqual(exportCatalog(gateway, "invoices", {pageSize:1}).entries.map(r=>r.id), ["1","2"]);
});
